import {backupDocumentsSchema,documentPaths,exportDocuments,validateDocumentManifest,stageBackupDocuments,readAnnotationBackup} from './backup-documents.ts';
import {rewriteAssetReferences} from '../documents.ts';
import { Reader, TextReader, ZipReader, ZipWriter, type CreateReadableOptions, type FileEntry } from '@zip.js/zip.js/lib/zip-core-native.js';
import { z } from 'zod';
import type { Workspace } from '../study';
import type { StoredImportJob } from './import-jobs';

// Binary archives bypass the legacy JSON endpoint. Every path is generated by
// StudySprint; user filenames are display metadata, never storage paths.
export const BACKUP_PART_SIZE = 8 * 1024 * 1024;
export const MAX_BACKUP_BYTES = 256 * 1024 * 1024;
export const MAX_BACKUP_ENTRIES = 20000;
const MAX_MANIFEST_BYTES = 4 * 1024 * 1024;
const MAX_METADATA_BYTES = 8 * 1024 * 1024;
const MAX_SOURCE_BYTES = 10 * 1024 * 1024;
const MAX_PREVIEW_BYTES = 40 * 1024 * 1024;
const MAX_NOTE_BYTES = 1024 * 1024;
const MAX_SOURCES = 200;
const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8', { fatal: true });
const id = z.string().min(1).max(100);
const sourceSchema = z.object({
    id, note: id, name: z.string().min(1).max(255), mediaType: z.enum(['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'text/markdown', 'text/plain']),
    size: z.number().int().positive().max(MAX_SOURCE_BYTES), preview: z.enum(['pdf', 'text']), derivedPreview: z.boolean(), ocr: z.boolean(),
    original: z.string().regex(/^sources\/\d{1,6}\/original$/), previewFile: z.string().regex(/^sources\/\d{1,6}\/preview\.pdf$/).optional(), previewSize: z.number().int().positive().max(MAX_PREVIEW_BYTES).optional(),
}).strict();
const manifestSchema = z.object({
    format: z.literal('studysprint'), version: z.union([z.literal(2),z.literal(3)]), exportedAt: z.string().datetime(), workspace: z.literal('workspace.json'),
    notes: z.array(z.object({ id, body: z.string().regex(/^notes\/\d{1,6}\.md$/), versions: z.array(z.object({ version: z.number().int().positive(), body: z.string().regex(/^revisions\/\d{1,6}\/\d{1,6}\.md$/) }).strict()).max(1000) }).strict()).max(5000),
    sources: z.array(sourceSchema).max(MAX_SOURCES),
    documents: backupDocumentsSchema.optional(),
}).strict();
export type BackupManifest = z.infer<typeof manifestSchema>;
type SourceRecord = { id: string; note: string; original_key: string; preview_key: string | null; name: string; media_type: string; size: number; preview_type: 'pdf' | 'text'; derived_preview: number; ocr: number };
type Part = { partNumber: number; etag: string; size: number };
type UploadState = { uploaded: Record<string, Part>; completing?: number; complete?: boolean; queued?: boolean; markdown?:boolean; folders?:boolean; subject?:string; newSubject?:string };
type UploadRow = { id: string; workspace: string; object_key: string; upload_id: string; name: string; size: number; parts: string; created: string };
type ExportFile = { path: string; size: number; text?: string; key?: string; etag?: string; note?: string; revision?: number; hash?: string; annotationBase?:string };

async function store() { return import('./workspace-store'); }
async function jobs() { return import('./import-jobs'); }
async function database() { const { env } = await import('cloudflare:workers'); if (!env.DB) throw Error('Database unavailable'); return env.DB; }
function response(data: unknown, status = 200) { return new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'private, no-store' } }); }
async function reject(status: number, message: string): Promise<never> { const { HttpError } = await store(); throw new HttpError(status, message); }
async function sameOrigin(req: Request) { const { checkOrigin } = await store(); checkOrigin(req); }
async function jsonInput(req: Request, max = 4096) {
    if(Number(req.headers.get('content-length'))>max)throw Error('Request is too large');
    if(!req.body)throw Error('Request is empty');
    const reader=req.body.getReader();const chunks:Uint8Array[]=[];let size=0;
    try{for(;;){const next=await reader.read();if(next.done)break;size+=next.value.byteLength;if(size>max){await reader.cancel();throw Error('Request is too large');}chunks.push(next.value);}}
    finally{reader.releaseLock();}
    const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.byteLength;}
    return JSON.parse(decoder.decode(bytes));
}
function assertSize(size: number, maximum: number, name: string) { if (!Number.isSafeInteger(size) || size < 0 || size > maximum) throw Error(`${name} exceeds the supported backup limit.`); }
function assertBackupWorkBudget(files: {path:string;size:number}[]) {
    const text = files.filter(file => /^(notes|revisions)\//.test(file.path));
    const binary = files.filter(file => file.path.startsWith('sources/')||file.path.startsWith('documents/'));
    const bytes = files.reduce((sum,file) => sum + file.size + 1024, 1024);
    const notes = text.filter(file=>file.path.startsWith('notes/'));
    const batches = Math.ceil((text.length+notes.length) / 32) + Math.ceil((text.reduce((sum,file) => sum + file.size,0)+notes.reduce((sum,file)=>sum+file.size,0)) / (8*1024*1024));
    // Reserve for SQL metadata, archive block reads, large native source reads,
    // source writes and retries under Workers' per-invocation I/O allowance.
    const restore = batches + binary.length + 3*binary.filter(file => file.size>MAX_NOTE_BYTES).length + 3*Math.ceil(bytes/(4*1024*1024)) + 25;
    const exporting = batches + 2*binary.length + 25;
    if (Math.max(restore,exporting)>900) throw Error('This workspace exceeds the file-processing limit for one complete ZIP backup. No records have been omitted.');
}

export function parseBackupManifest(value: unknown): BackupManifest {
    const result = manifestSchema.parse(value);
    const paths = new Set(['manifest.json', 'workspace.json']);
    const notes = new Set<string>();
    const sources = new Set<string>();
    const sourceNotes = new Set<string>();
    const add = (path: string) => { if (paths.has(path)) throw Error('Backup has duplicate file paths.'); paths.add(path); };
    for (const note of result.notes) {
        if (notes.has(note.id)) throw Error('Backup has duplicate note identifiers.');
        notes.add(note.id); add(note.body);
        const versions = new Set<number>();
        for (const revision of note.versions) { if (versions.has(revision.version)) throw Error('Backup has duplicate revisions.'); versions.add(revision.version); add(revision.body); }
    }
    for (const source of result.sources) {
        if (sources.has(source.id) || sourceNotes.has(source.note)) throw Error('Backup has duplicate source identifiers.');
        if (!notes.has(source.note)) throw Error('Backup source references a missing note.');
        sources.add(source.id); sourceNotes.add(source.note); add(source.original);
        if (!!source.previewFile !== !!source.previewSize) throw Error('Backup preview metadata is incomplete.');
        if (source.preview === 'text' && (source.previewFile || source.derivedPreview || source.ocr)) throw Error('Backup text source has invalid preview metadata.');
        if (result.version===2&&(source.preview === 'text') !== source.mediaType.startsWith('text/')) throw Error('Backup source has an incompatible preview type.');
        if (source.preview === 'pdf' && source.mediaType !== 'application/pdf' && !source.previewFile) throw Error('Backup is missing a document preview.');
        if (source.derivedPreview && !source.previewFile) throw Error('Backup is missing its derived preview.');
        if (source.previewFile) add(source.previewFile);
    }
    if(result.version===3&&!result.documents)throw Error('Backup v3 is missing document metadata.');
    if(result.version===2&&result.documents)throw Error('Backup v2 cannot contain document metadata.');
    if(result.documents){validateDocumentManifest(result.documents,notes,sourceNotes);for(const path of documentPaths(result.documents))add(path);}
    if (paths.size > MAX_BACKUP_ENTRIES) throw Error('Backup contains too many files.');
    return result;
}

export function expectedBackupPaths(manifest: BackupManifest) {
    const paths = new Set(['manifest.json', 'workspace.json']);
    for (const note of manifest.notes) { paths.add(note.body); for (const revision of note.versions) paths.add(revision.body); }
    for (const source of manifest.sources) { paths.add(source.original); if (source.previewFile) paths.add(source.previewFile); }
    for(const path of documentPaths(manifest.documents))paths.add(path);
    return paths;
}

// ZipReader needs random access to its central directory. Passing an R2 body
// stream directly would buffer the entire archive inside zip.js.
export class R2BackupReader extends Reader<undefined> {
    private blocks = new Map<number, Uint8Array>();
    private bucket: R2Bucket;
    private key: string;
    constructor(bucket: R2Bucket, key: string, size: number) { super(undefined); this.bucket=bucket;this.key=key;this.size = size; }
    async readUint8Array(offset: number, length: number): Promise<Uint8Array> {
        this.checkRange(offset, length);
        length = Math.min(length, this.size - offset);
        // Central directory and headers are the only random-access buffers.
        // File data uses createReadable, so a hostile ZIP cannot allocate a
        // 256 MiB central-directory buffer inside a 128 MiB Worker.
        assertSize(length, MAX_METADATA_BYTES, 'ZIP directory');
        if (!length) return new Uint8Array();
        const bytes = new Uint8Array(length); let written = 0;
        while (written < length) {
            const start = Math.floor((offset + written) / (4 * 1024 * 1024)) * (4 * 1024 * 1024);
            let block = this.blocks.get(start);
            if (block) { this.blocks.delete(start); this.blocks.set(start, block); }
            else {
                const count = Math.min(4 * 1024 * 1024, this.size - start);
                const object = await this.bucket.get(this.key, { range: { offset: start, length: count } });
                if (!object || !('body' in object)) throw Error('Staged backup is unavailable.');
                block = new Uint8Array(await object.arrayBuffer());
                if (block.byteLength !== count) throw Error('Staged backup is incomplete.');
                this.blocks.set(start, block);
                if (this.blocks.size > 3) this.blocks.delete(this.blocks.keys().next().value!);
            }
            const inBlock = offset + written - start;
            const count = Math.min(length - written, block.byteLength - inBlock);
            bytes.set(block.subarray(inBlock, inBlock + count), written); written += count;
        }
        return bytes;
    }
    createReadable(options: CreateReadableOptions = {}): ReadableStream<Uint8Array> {
        const offset = options.offset || 0;
        const length = options.size ?? this.size - offset;
        this.checkRange(offset, length);
        if (length <= MAX_NOTE_BYTES) {
            let cursor = 0;
            return new ReadableStream<Uint8Array>({ pull: async controller => { try { if (cursor === length) { controller.close(); return; } const bytes = await this.readUint8Array(offset + cursor, Math.min(65536, length - cursor)); if (!bytes.byteLength) throw Error('Staged backup is incomplete.'); cursor += bytes.byteLength; controller.enqueue(bytes); } catch (error) { controller.error(error); } } });
        }
        let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
        return new ReadableStream<Uint8Array>({
            start: async controller => {
                if (!length) { controller.close(); return; }
                try { const object = await this.bucket.get(this.key, { range: { offset, length } }); if (!object || !('body' in object)) throw Error('Staged backup is unavailable.'); reader = object.body.getReader(); }
                catch (error) { controller.error(error); }
            },
            pull: async controller => { if (!reader) return; try { const next = await reader.read(); if (next.done) controller.close(); else controller.enqueue(next.value); } catch (error) { controller.error(error); } },
            cancel: async reason => { await reader?.cancel(reason); },
        });
    }
    private checkRange(offset: number, length: number) { if (!Number.isSafeInteger(offset) || !Number.isSafeInteger(length) || offset < 0 || length < 0 || offset > this.size) throw Error('Invalid backup byte range.'); }
}

async function sourceFiles(workspace: string): Promise<SourceRecord[]> { const db = await database(); const rows = await db.prepare('SELECT id,note,original_key,preview_key,name,media_type,size,preview_type,derived_preview,ocr FROM note_sources WHERE workspace=?').bind(workspace).all<SourceRecord>(); return rows.results; }

export async function exportBackup(req: Request): Promise<Response> {
    const { requireWorkspaceId, readSnapshot, getBucket } = await store();
    const workspaceId = await requireWorkspaceId(req);
    const db = await database();
    // Bound metadata before readSnapshot parses it. In particular, review
    // history and thousands of aliases must not allocate an oversized document
    // merely to discover that it cannot fit in a portable backup.
    const metadataSize=await db.prepare('SELECT COALESCE((SELECT length(CAST(data AS BLOB)) FROM workspaces WHERE id=?),0)+COALESCE((SELECT sum(length(CAST(data AS BLOB))) FROM notes WHERE workspace=?),0)+COALESCE((SELECT sum(length(CAST(data AS BLOB))) FROM review_events WHERE workspace=?),0)+128*(SELECT count(*) FROM note_revisions WHERE workspace=?) AS size').bind(workspaceId,workspaceId,workspaceId,workspaceId).first<{size:number}>();
    assertSize(metadataSize?.size||0,MAX_METADATA_BYTES,'Workspace metadata');
    const [{ workspace, version }, sources] = await Promise.all([readSnapshot(workspaceId), sourceFiles(workspaceId)]);
    const noteRows = (await db.prepare('SELECT id,data,hash,length(CAST(body AS BLOB)) AS size FROM notes WHERE workspace=? ORDER BY rowid').bind(workspaceId).all<{id:string;data:string;hash:string;size:number}>()).results;
    const revisions = (await db.prepare('SELECT note,version,at,length(CAST(body AS BLOB)) AS size FROM note_revisions WHERE workspace=? ORDER BY version').bind(workspaceId).all<{note:string;version:number;at:string;size:number}>()).results;
    const end = await db.prepare('SELECT version FROM workspaces WHERE id=?').bind(workspaceId).first<{version:number}>();
    if (end?.version !== version) return reject(409, 'Your workspace changed while preparing the backup. Download it again.');
    if (sources.length > MAX_SOURCES) throw Error(`This workspace exceeds the limit of ${MAX_SOURCES} original files for one complete ZIP backup. No files have been omitted.`);
    const bucket = getBucket();
    const manifest: BackupManifest = { format: 'studysprint', version: 3, documents:{assets:[],bases:[]}, exportedAt: new Date().toISOString(), workspace: 'workspace.json', notes: [], sources: [] };
    const files: ExportFile[] = [];
    const revisionsByNote=new Map<string,typeof revisions>();for(const revision of revisions){const list=revisionsByNote.get(revision.note)||[];list.push(revision);revisionsByNote.set(revision.note,list);}
    const metadata = { ...workspace, notes: noteRows.map((row, index) => {
        const { preview: _preview, linkTitles: _linkTitles, ...note } = JSON.parse(row.data);
        assertSize(row.size, MAX_NOTE_BYTES, 'Note');
        const path = `notes/${index + 1}.md`;
        files.push({ path, note: row.id, hash: row.hash, size: row.size });
        const savedRevisions = revisionsByNote.get(row.id)||[];
        const descriptors = savedRevisions.map((revision, number) => {
            assertSize(revision.size, MAX_NOTE_BYTES, 'Note revision');
            const revisionPath = `revisions/${index + 1}/${number + 1}.md`;
            files.push({ path: revisionPath, note: row.id, revision: revision.version, size: revision.size });
            return { version: revision.version, body: revisionPath };
        });
        manifest.notes.push({ id: note.id, body: path, versions: descriptors });
        return { ...note, versions: savedRevisions.map(({ note: _note, size: _size, ...revision }) => revision) };
    }) };
    const attached = new Set(sources.map(source => source.note));
    if (workspace.notes.some(note => note.source && !attached.has(note.id))) throw Error('An original file record is unavailable; the backup was not created.');
    for (const [index, source] of sources.entries()) {
        if (!workspace.notes.some(note => note.id === source.note)) throw Error('An original file is missing its note; the backup was not created.');
        const original = await bucket.head(source.original_key);
        if (!original || original.size !== source.size) throw Error(`Original file “${source.name}” is unavailable; the backup was not created.`);
        const item: BackupManifest['sources'][number] = { id: source.id, note: source.note, name: source.name, mediaType: source.media_type as BackupManifest['sources'][number]['mediaType'], size: source.size, preview: source.preview_type, derivedPreview: !!source.derived_preview, ocr: !!source.ocr, original: `sources/${index + 1}/original` };
        files.push({ path: item.original, key: source.original_key, size: original.size, etag: original.etag });
        if (source.preview_key) {
            const preview = await bucket.head(source.preview_key);
            if (!preview) throw Error(`Preview for “${source.name}” is unavailable; the backup was not created.`);
            item.previewFile = `sources/${index + 1}/preview.pdf`; item.previewSize = preview.size;
            files.push({ path: item.previewFile, key: source.preview_key, size: preview.size, etag: preview.etag });
        }
        manifest.sources.push(item);
    }
    const rich=await exportDocuments(workspaceId);manifest.documents=rich.documents;files.push(...rich.files);
    parseBackupManifest(manifest);
    const manifestText = JSON.stringify(manifest);
    const workspaceText = JSON.stringify(metadata);
    assertSize(encoder.encode(manifestText).byteLength, MAX_MANIFEST_BYTES, 'Backup manifest');
    assertSize(encoder.encode(workspaceText).byteLength, MAX_METADATA_BYTES, 'Workspace metadata');
    files.unshift({ path: 'workspace.json', text: workspaceText, size: encoder.encode(workspaceText).byteLength });
    files.unshift({ path: 'manifest.json', text: manifestText, size: encoder.encode(manifestText).byteLength });
    // STORE entries use data descriptors and a small central directory. Reserve
    // a conservative 1 KiB per entry so every exported ZIP can be restored.
    const estimatedBytes=files.reduce((sum, file) => sum + file.size + 1024, 1024);
    assertSize(estimatedBytes, MAX_BACKUP_BYTES, 'Complete backup');
    assertBackupWorkBudget(files);
    if (files.length > MAX_BACKUP_ENTRIES) throw Error('The backup contains too many files.');
    if(new URL(req.url).searchParams.get('check')==='1')return response({ready:true,estimatedBytes,version});
    const stream = new TransformStream<Uint8Array, Uint8Array>();
    const archive = new ZipWriter(stream.writable, { level: 0, useWebWorkers: false, bufferedWrite: false, dataDescriptor: true });
    // The response owns this task: zip.js honors the stream's backpressure and
    // rejects outstanding reads when the browser cancels its download.
    void (async () => {
        try {
            for (let index = 0; index < files.length; index++) {
                const file = files[index];
                if (file.text !== undefined) await archive.add(file.path, new TextReader(file.text));
                else if(file.annotationBase){const content=await readAnnotationBackup(workspaceId,file.annotationBase);if(await (await store()).digest(content)!==file.hash)throw Error('Annotations changed while exporting. Download the backup again.');await archive.add(file.path,new TextReader(content));}
                else if (file.note) {
                    const group: ExportFile[] = []; let bytes = 0;
                    while (index < files.length && files[index].note && group.length < 32 && bytes + files[index].size <= 8 * 1024 * 1024) { group.push(files[index]); bytes += files[index].size; index++; }
                    index--;
                    const rows = await db.batch<{body:string}>(group.map(item => item.revision === undefined ? db.prepare('SELECT body FROM notes WHERE workspace=? AND id=? AND hash=?').bind(workspaceId,item.note,item.hash) : db.prepare('SELECT body FROM note_revisions WHERE workspace=? AND note=? AND version=?').bind(workspaceId,item.note,item.revision)));
                    for (let number = 0; number < group.length; number++) { const body = rows[number].results[0]?.body; if (body === undefined || encoder.encode(body).byteLength !== group[number].size) throw Error('A note changed while exporting. Download the backup again.'); await archive.add(group[number].path, new TextReader(body)); }
                } else { const object = await bucket.get(file.key!, { onlyIf: { etagMatches: file.etag! } }); if (!object || !('body' in object)) throw Error('A source changed while exporting. Download the backup again.'); await archive.add(file.path, object.body); }
            }
            await archive.close();
        } catch (error) { try { await stream.writable.abort(error); } catch { /* The writer may already have aborted the response. */ } }
    })();
    return new Response(stream.readable, { headers: { 'Content-Type': 'application/zip', 'Content-Disposition': `attachment; filename="studysprint-backup-${new Date().toISOString().slice(0, 10)}.zip"`, 'Cache-Control': 'private, no-store', 'X-Content-Type-Options': 'nosniff' } });
}

export async function startBackupUpload(req: Request): Promise<Response> {
    await sameOrigin(req);
    const { requireWorkspaceId, getBucket } = await store();
    const workspace = await requireWorkspaceId(req);
    const {env}=await import('cloudflare:workers');if(!env.IMPORT_QUEUE)return reject(503,'Background backup restoration is not configured.');
    const input = z.object({ name: z.string().trim().min(1).max(255), size: z.number().int().min(22).max(MAX_BACKUP_BYTES),markdown:z.boolean().optional(),folders:z.boolean().optional(),subject:z.string().max(100).optional(),newSubject:z.string().max(100).optional() }).strict().parse(await jsonInput(req));
    if (!/\.zip$/i.test(input.name)) throw Error('Choose a StudySprint .zip backup.');
    const uploadId = crypto.randomUUID();
    const key = `workspaces/${workspace}/backups/${uploadId}.zip`;
    const upload = await getBucket().createMultipartUpload(key, { httpMetadata: { contentType: 'application/zip' } });
    try { const db = await database(); await db.prepare('INSERT INTO backup_uploads(id,workspace,object_key,upload_id,name,size,parts,created) VALUES(?,?,?,?,?,?,?,?)').bind(uploadId, workspace, key, upload.uploadId, input.name, input.size, JSON.stringify({ uploaded: {},markdown:input.markdown,folders:input.folders,subject:input.subject,newSubject:input.newSubject }), new Date().toISOString()).run(); }
    catch (error) { await upload.abort(); throw error; }
    return response({ id: uploadId, partSize: BACKUP_PART_SIZE }, 201);
}

async function ownedUpload(req: Request, uploadId: string) {
    const { requireWorkspaceId } = await store();
    const workspace = await requireWorkspaceId(req);
    const db = await database();
    const row = await db.prepare('SELECT * FROM backup_uploads WHERE id=? AND workspace=?').bind(uploadId, workspace).first<UploadRow>();
    if (!row) return reject(404, 'Backup upload unavailable.');
    return { row, db, state: JSON.parse(row.parts) as UploadState };
}

export function backupPartSize(total: number, number: number) {
    if (!Number.isInteger(number) || number < 1 || number > Math.ceil(total / BACKUP_PART_SIZE)) throw Error('Invalid backup part number.');
    return Math.min(BACKUP_PART_SIZE, total - (number - 1) * BACKUP_PART_SIZE);
}

export async function uploadBackupPart(req: Request, uploadId: string): Promise<Response> {
    await sameOrigin(req);
    const { getBucket } = await store();
    const { row, db, state } = await ownedUpload(req, uploadId);
    if (state.completing || state.complete) return reject(409, 'The backup upload is already being completed.');
    const number = Number(new URL(req.url).searchParams.get('part'));
    const size = backupPartSize(row.size, number);
    if (state.uploaded[number]) return response({ partNumber: number, etag: state.uploaded[number].etag });
    if (!req.body) throw Error('The backup part is empty.');
    const declared = req.headers.get('content-length');
    if (declared !== null && Number(declared) !== size) throw Error('Backup part size does not match.');
    const upload = getBucket().resumeMultipartUpload(row.object_key, row.upload_id);
    const part = await upload.uploadPart(number, req.body.pipeThrough(new FixedLengthStream(size)));
    for (let attempt = 0; attempt < 5; attempt++) {
        const current = await db.prepare('SELECT parts FROM backup_uploads WHERE id=? AND workspace=?').bind(row.id, row.workspace).first<{ parts: string }>();
        if (!current) throw Error('Backup upload was cancelled.');
        const next = JSON.parse(current.parts) as UploadState;
        if (next.completing || next.complete) return reject(409, 'The backup upload is already being completed.');
        next.uploaded[number] = { ...part, size };
        const saved = await db.prepare('UPDATE backup_uploads SET parts=? WHERE id=? AND workspace=? AND parts=?').bind(JSON.stringify(next), row.id, row.workspace, current.parts).run();
        if (saved.meta.changes) return response(part);
    }
    return reject(409, 'Another upload part changed. Retry this part.');
}

export async function finishBackupUpload(req: Request, uploadId: string): Promise<Response> {
    await sameOrigin(req);
    const { getBucket } = await store();
    const { row, db, state } = await ownedUpload(req, uploadId);
    const { action } = z.object({ action: z.enum(['complete', 'cancel']) }).strict().parse(await jsonInput(req));
    const bucket = getBucket();
    const upload = bucket.resumeMultipartUpload(row.object_key, row.upload_id);
    if (action === 'cancel') {
        if (state.queued || state.completing) return reject(409, 'This backup is already being completed. Cancel it from the import list.');
        if (!state.complete) { try { await upload.abort(); } catch { /* Completion may have won the race; delete its staged object below. */ } }
        await bucket.delete(row.object_key);
        await db.prepare('DELETE FROM backup_uploads WHERE id=? AND workspace=?').bind(row.id, row.workspace).run();
        return response({ cancelled: true });
    }
    const parts = Object.values(state.uploaded).sort((a, b) => a.partNumber - b.partNumber);
    if (parts.length !== Math.ceil(row.size / BACKUP_PART_SIZE) || parts.some((part, index) => part.partNumber !== index + 1 || part.size !== backupPartSize(row.size, part.partNumber))) throw Error('Upload all backup parts before completing it.');
    if (!state.complete) {
        if (state.completing && state.completing > Date.now() - 60000) return reject(409, 'Backup completion is already in progress. Retry in a moment.');
        const locked = { ...state, completing: Date.now() };
        const changed = await db.prepare('UPDATE backup_uploads SET parts=? WHERE id=? AND workspace=? AND parts=?').bind(JSON.stringify(locked), row.id, row.workspace, row.parts).run();
        if (!changed.meta.changes) return reject(409, 'The upload changed. Retry completion.');
        try {
            // Recover when R2 completed successfully but the HTTP response or
            // the following D1 update was lost.
            const completed = await bucket.head(row.object_key) || await upload.complete(parts.map(({ partNumber, etag }) => ({ partNumber, etag })));
            if (completed.size !== row.size) throw Error('The completed backup size does not match.');
            state.complete = true;
            delete state.completing;
            await db.prepare('UPDATE backup_uploads SET parts=? WHERE id=? AND workspace=?').bind(JSON.stringify(state), row.id, row.workspace).run();
        } catch (error) { delete state.completing; await db.prepare('UPDATE backup_uploads SET parts=? WHERE id=? AND workspace=?').bind(JSON.stringify(state), row.id, row.workspace).run(); throw error; }
    }
    const { createImportJob, enqueueImportJob, publicJob, failImport } = await jobs();
    const job = await createImportJob(row.workspace, { id: row.id, kind: 'restore', name: row.name, title: row.name.replace(/\.zip$/i, ''), originalKey: row.object_key, mediaType: 'application/zip', size: row.size,payload:{markdown:state.markdown||false,folders:state.folders,subject:state.subject,newSubject:state.newSubject} });
    if (!state.queued && job.status === 'queued') { try { await enqueueImportJob(job.id); } catch (error) { await failImport(job.id, (error as Error).message); throw error; } }
    state.queued = true;
    await db.prepare('UPDATE backup_uploads SET parts=? WHERE id=? AND workspace=?').bind(JSON.stringify(state), row.id, row.workspace).run();
    return response({ job: publicJob(job) }, 202);
}

export async function backupError(error: unknown) { const { errorResponse } = await store(); return errorResponse(error); }

export async function readBackupText(entry: FileEntry, maximum: number): Promise<string> {
    assertSize(entry.uncompressedSize, maximum, entry.filename);
    const chunks: Uint8Array[] = []; let size = 0;
    await entry.getData(new WritableStream<Uint8Array>({ write(chunk) { size += chunk.byteLength; assertSize(size, maximum, entry.filename); chunks.push(chunk); } }), { checkCrc32: true, useWebWorkers: false });
    if (size !== entry.uncompressedSize) throw Error('Backup entry size does not match.');
    const bytes = new Uint8Array(size); let offset = 0; for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
    return decoder.decode(bytes);
}

async function restoreId(job: string, kind: string, old: string) { const bytes = new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(JSON.stringify([job, kind, old])))).slice(0, 16); bytes[6] = (bytes[6] & 15) | 64; bytes[8] = (bytes[8] & 63) | 128; const hex = [...bytes].map(value => value.toString(16).padStart(2, '0')).join(''); return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`; }

export async function processRestoreJob(job: StoredImportJob): Promise<void> {
    if(job.payload.markdown){const{processMarkdownArchive}=await import('./markdown-bundles');return processMarkdownArchive(job);}
    const { getBucket, readSnapshot, publishStagedRestore } = await store();
    const db = await database();
    const bucket = getBucket();
    const object = await bucket.head(job.originalKey);
    if (!object || object.size !== job.size) throw Error('The uploaded backup is unavailable or incomplete.');
    assertSize(object.size, MAX_BACKUP_BYTES, 'Backup');
    const archive = new ZipReader(new R2BackupReader(bucket, job.originalKey, object.size), { useWebWorkers: false, checkCrc32: true, checkLocalDirectory: true, checkLocalFilename: true, checkOverlappingEntry: true, checkAmbiguity: true });
    const stagedKeys: string[] = [];
    let published = false;
    try {
        const entries = await archive.getEntries();
        if (entries.length > MAX_BACKUP_ENTRIES) throw Error('Backup contains too many files.');
        const byPath = new Map<string, FileEntry>(); let total = 0;
        for (const entry of entries) {
            if (entry.directory || entry.encrypted || byPath.has(entry.filename)) throw Error('Backup contains duplicate, encrypted or unexpected entries.');
            if (entry.compressionMethod !== 0 && entry.compressionMethod !== 8) throw Error('Unsupported backup compression.');
            total += entry.uncompressedSize; assertSize(total, MAX_BACKUP_BYTES, 'Expanded backup'); byPath.set(entry.filename, entry);
        }
        const manifestEntry = byPath.get('manifest.json');
        if (!manifestEntry) throw Error('Choose a StudySprint ZIP backup.');
        const manifest = parseBackupManifest(JSON.parse(await readBackupText(manifestEntry, MAX_MANIFEST_BYTES)));
        const expected = expectedBackupPaths(manifest);
        if (expected.size !== byPath.size || [...expected].some(path => !byPath.has(path))) throw Error('Backup contains missing or unexpected files.');
        if([...expected].some((path,index)=>entries[index].filename!==path||(index>0&&entries[index].offset<=entries[index-1].offset)))throw Error('Restore an unchanged StudySprint ZIP backup. Its file order has been modified.');
        assertBackupWorkBudget([...byPath].map(([path, entry]) => ({path,size:entry.uncompressedSize})));
        const metadata = JSON.parse(await readBackupText(byPath.get('workspace.json')!, MAX_METADATA_BYTES));
        if (!metadata || !Array.isArray(metadata.notes) || metadata.notes.length !== manifest.notes.length) throw Error('Backup note metadata does not match its manifest.');
        const noteMetadata = new Map<string, any>();
        for (const note of metadata.notes) { if (!note || typeof note.id !== 'string' || noteMetadata.has(note.id)) throw Error('Backup has duplicate or invalid notes.'); noteMetadata.set(note.id, note); }
        const { importBackup } = await import('../backup');
        const { notePreview, links } = await import('../study');
        // Validate the small metadata document first. Text is validated and
        // staged one entry at a time, never assembled into a giant workspace.
        const restored: Workspace = { subjects: [], notes: [], cards: [], events: [], limit: 10, zone: 'UTC' };
        importBackup(restored, { format: 'studysprint', version: 1, workspace: {...metadata, notes:[]} });
        const remapped = new Map<string, string>();
        for (const kind of ['subjects', 'notes', 'cards', 'events'] as const) for (const record of metadata[kind]) remapped.set(`${kind}:${record.id}`, await restoreId(job.id, kind, record.id));
        const mapped = async (kind: string, value: string) => { if(!value)return '';const key=`${kind}:${value}`;if(!remapped.has(key))remapped.set(key,await restoreId(job.id,kind,value));return remapped.get(key)!; };
        const assetMap=new Map<string,string>();for(const item of manifest.documents?.assets||[])assetMap.set(item.data.id,await mapped('assets',item.data.id));
        const restoreBody=(body:string,note:string)=>{for(const match of body.matchAll(/asset:([a-f0-9-]{36})/gi)){if(!manifest.documents?.assets.some(a=>a.data.id===match[1]&&a.note===note))throw Error('Backup Markdown references an unavailable image.');}return rewriteAssetReferences(body,assetMap);};
        const sourceNotes = new Map<string, string>();
        for (let index=0;index<restored.subjects.length;index++)restored.subjects[index].id=await mapped('subjects',metadata.subjects[index].id);
        for (let index=0;index<restored.cards.length;index++){const card=restored.cards[index],raw=metadata.cards[index];card.id=await mapped('cards',raw.id);card.subject=await mapped('subjects',raw.subject);if(raw.note)card.note=await mapped('notes',raw.note);}
        for (let index=0;index<restored.events.length;index++){const event=restored.events[index],raw=metadata.events[index];event.id=await mapped('events',raw.id);event.card=await mapped('cards',raw.card);}
        let pending:D1PreparedStatement[]=[];let pendingBytes=0;
        const flush=async()=>{if(pending.length){await db.batch(pending);pending=[];pendingBytes=0;}};
        const stage=async(statement:D1PreparedStatement,bytes=0)=>{if(pending.length&&(pending.length>=32||pendingBytes+bytes>8*1024*1024))await flush();pending.push(statement);pendingBytes+=bytes;};
        // A retry replaces only this job's invisible staging records.
        await db.batch(['restore_notes','restore_revisions','restore_sources','restore_documents'].map(table=>db.prepare(`DELETE FROM ${table} WHERE job=? AND workspace=?`).bind(job.id,job.workspace)));
        const subjectIds=new Set(metadata.subjects.map((subject:any)=>subject.id));
        const revisionSchema=z.object({version:z.number().int().positive(),at:z.string().datetime()});
        for (const descriptor of manifest.notes) {
            const raw=noteMetadata.get(descriptor.id);
            if(!raw||!Array.isArray(raw.versions)||raw.versions.length!==descriptor.versions.length)throw Error('Backup is missing note revisions.');
            if(raw.subject&&!subjectIds.has(raw.subject))throw Error('Backup note references a missing subject.');
            const body=restoreBody(await readBackupText(byPath.get(descriptor.body)!,MAX_NOTE_BYTES),raw.id);
            const checked:Workspace={subjects:[],notes:[],cards:[],events:[],limit:10,zone:'UTC'};
            importBackup(checked,{format:'studysprint',version:1,workspace:{subjects:raw.subject?[{id:raw.subject,name:'Validation'}]:[],notes:[{...raw,body,versions:[]}],cards:[],events:[]}});
            const note=checked.notes[0];note.id=await mapped('notes',raw.id);note.subject=await mapped('subjects',raw.subject);note.bindings=Object.fromEntries(await Promise.all(Object.entries(raw.bindings||{}).map(async([title,target])=>[title,await mapped('notes',target as string)])));
            if(raw.conversion)note.conversion=z.object({engine:z.string().max(100),warnings:z.array(z.string().max(2000)).max(200)}).parse(raw.conversion);
            const {body:_body,versions:_versions,source:_source,...record}=note;
            const bodyHash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(body)))].map(value=>value.toString(16).padStart(2,'0')).join('');
            const data=JSON.stringify({...record,preview:notePreview(note),linkTitles:[...new Set(links(body))],bodyHash});
            assertSize(encoder.encode(data).byteLength+encoder.encode(body).byteLength,1800000,'Restored note record');
            const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(data+'\n'+body)))].map(value=>value.toString(16).padStart(2,'0')).join('');
            await stage(db.prepare('INSERT OR REPLACE INTO restore_notes(job,workspace,id,data,body,hash) VALUES(?,?,?,?,?,?)').bind(job.id,job.workspace,note.id,data,body,hash),encoder.encode(data+body).byteLength);
            const search=(note.title+' '+body).toLowerCase();assertSize(encoder.encode(search).byteLength,1800000,'Restored search record');
            await stage(db.prepare('INSERT OR REPLACE INTO note_search(workspace,id,content) VALUES(?,?,?)').bind(job.workspace,note.id,search),encoder.encode(search).byteLength);
            sourceNotes.set(raw.id,note.id);
            const revisions=new Map<number,{version:number;at:string}>();
            for(const value of raw.versions){const revision=revisionSchema.parse(value);if(revisions.has(revision.version)||revision.version>=note.version)throw Error('Backup contains invalid revision versions.');revisions.set(revision.version,revision);}
            for(const revision of descriptor.versions){const record=revisions.get(revision.version);if(!record)throw Error('Backup revision metadata does not match.');const body=restoreBody(await readBackupText(byPath.get(revision.body)!,MAX_NOTE_BYTES),raw.id);await stage(db.prepare('INSERT OR REPLACE INTO restore_revisions(job,workspace,note,version,body,at) VALUES(?,?,?,?,?,?)').bind(job.id,job.workspace,note.id,record.version,body,record.at),encoder.encode(body).byteLength);}
        }
        await flush();
        const copy = async (path: string, key: string, size: number, mediaType: string,sha?:string,note?:string) => {
                const entry = byPath.get(path)!; if (entry.uncompressedSize !== size) throw Error('A backup source size does not match.');
                let count = 0;const hasher=sha?(await import('node:crypto')).createHash('sha256'):null;
                const stream = new FixedLengthStream(size);
                const{trackFile,verifyDocumentFile}=await import('./documents');await trackFile(job,note||'',key,'restore');stagedKeys.push(key);
                const put = bucket.put(key, stream.readable, { httpMetadata: { contentType: mediaType } });
                const writer = stream.writable.getWriter();
                try { await entry.getData(new WritableStream<Uint8Array>({
                    async write(chunk) { hasher?.update(chunk);count += chunk.byteLength; if (count > size) throw Error('Backup source exceeds its declared size.'); await writer.write(chunk); },
                    async close() { if (count !== size) throw Error('Backup source is incomplete.');if(hasher&&hasher.digest('hex')!==sha)throw Error('Document artifact checksum does not match.'); await writer.close(); },
                    async abort(reason) { await writer.abort(reason); },
                }), { checkCrc32: true, useWebWorkers: false }); await put;await verifyDocumentFile(job,key); }
                catch (error) { try { await writer.abort(error); } catch { /* The sink may already be closed. */ } await put.catch(() => {}); throw error; }
            };
        for (const source of manifest.sources) {
            const sourceId = await restoreId(job.id, 'sources', source.id);
            const note = sourceNotes.get(source.note)!;
            const originalKey = `workspaces/${job.workspace}/sources/${sourceId}/original`;
            const previewKey = source.previewFile ? `workspaces/${job.workspace}/sources/${sourceId}/preview.pdf` : null;
            await copy(source.original, originalKey, source.size, source.mediaType,undefined,note);
            if (source.previewFile) await copy(source.previewFile, previewKey!, source.previewSize!, 'application/pdf',undefined,note);
            await stage(db.prepare('INSERT OR REPLACE INTO restore_sources(job,id,workspace,note,original_key,preview_key,name,media_type,size,preview_type,derived_preview,ocr) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').bind(job.id,sourceId,job.workspace,note,originalKey,previewKey,source.name,source.mediaType,source.size,source.preview,source.derivedPreview?1:0,source.ocr?1:0));
        }
        await flush();
        if(manifest.documents)await stageBackupDocuments(job,manifest.documents,mapped,(path,max)=>readBackupText(byPath.get(path)!,max),copy);
        await flush();
        for (let attempt = 0; attempt < 5; attempt++) {
            const current = await readSnapshot(job.workspace);
            const {notes:_notes,...next}=structuredClone(current.workspace);
            for (const kind of ['subjects', 'cards', 'events'] as const) (next[kind] as any[]).push(...restored[kind].filter(record => !next[kind].some(existing => existing.id === record.id)));
            if (!current.workspace.notes.length && !current.workspace.cards.length && !current.workspace.subjects.length) {
                if (Number.isInteger(metadata.limit) && metadata.limit >= 0 && metadata.limit <= 100) next.limit = metadata.limit;
                if (typeof metadata.zone === 'string') { new Intl.DateTimeFormat('en', { timeZone: metadata.zone }); next.zone = metadata.zone; }
            }
            try { await publishStagedRestore(job.workspace,next,current.version,{id:job.id,token:job.token});published=true;break; }
            catch (error) { if ((error as { status?: number }).status !== 409 || attempt === 4) throw error; }
        }
        // The consumer removes the staging archive only after recording ready.
        // Retaining it until then makes a lost completion acknowledgement safe.
    } finally {
        await archive.close();
        if(!published)try{await db.batch([db.prepare('DELETE FROM note_search WHERE workspace=? AND id IN(SELECT id FROM restore_notes WHERE job=? AND workspace=?) AND NOT EXISTS(SELECT 1 FROM notes WHERE notes.workspace=note_search.workspace AND notes.id=note_search.id)').bind(job.workspace,job.id,job.workspace),...['restore_notes','restore_revisions','restore_sources','restore_documents'].map(table=>db.prepare(`DELETE FROM ${table} WHERE job=? AND workspace=?`).bind(job.id,job.workspace))]);}catch{/* Staging is never visible and can be cleared by later cleanup. */}
        if (!published && stagedKeys.length) {
            // A database timeout can hide a successful commit. Never remove a
            // source until we have positively checked it is still unreferenced.
            try { const references = new Set((await sourceFiles(job.workspace)).flatMap(source => [source.original_key, source.preview_key]).filter(Boolean)); const rich=await db.prepare('SELECT object_key FROM document_files WHERE workspace=? AND published=1').bind(job.workspace).all<{object_key:string}>();rich.results.forEach(row=>references.add(row.object_key));const unused = stagedKeys.filter(key => !references.has(key)); if (unused.length) await bucket.delete(unused); } catch { /* Keep uncertain objects for later orphan cleanup. */ }
        }
    }
}
